class Solution:
    def canTraverseAllPairs(self, nums: list[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            a, b = find(a), find(b)
            if a != b:
                parent[a] = b
        prime_to_idx = {}
        for i in range(n):
            num = nums[i]
            d = 2
            while d * d <= num:
                if num % d == 0:
                    if d in prime_to_idx:
                        union(i, prime_to_idx[d])
                    else:
                        prime_to_idx[d] = i
                    while num % d == 0:
                        num //= d
                d += 1
            if num > 1:
                if num in prime_to_idx:
                    union(i, prime_to_idx[num])
                else:
                    prime_to_idx[num] = i
        root = find(0)
        return all(find(i) == root for i in range(n))
